/// Error returned when decoding a generator's binary encoding fails.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct UnmarshalError(&'static str);

impl fmt::Display for UnmarshalError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.0)
    }
}

impl std::error::Error for UnmarshalError {}

/// Go's `rand.Source`: a stream of uniformly distributed `u64` values.
pub trait Source {
    /// Return the next value in the stream.
    fn uint64(&mut self) -> u64;
}

impl<S: Source + ?Sized> Source for &mut S {
    fn uint64(&mut self) -> u64 {
        (**self).uint64()
    }
}

impl<S: Source + ?Sized> Source for Box<S> {
    fn uint64(&mut self) -> u64 {
        (**self).uint64()
    }
}

/// Go's `rand.Rand`: distributions derived from a [`Source`].
///
/// Methods that take a bound panic, as Go does, when the bound is not
/// positive.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rand<S> {
    src: S,
}

impl<S: Source> Rand<S> {
    /// Go's `rand.New(src)`.
    pub fn new(src: S) -> Self {
        Self { src }
    }

    /// Borrow the underlying source.
    pub fn source(&self) -> &S {
        &self.src
    }

    /// Mutably borrow the underlying source, for example to reseed it.
    pub fn source_mut(&mut self) -> &mut S {
        &mut self.src
    }

    /// Return the underlying source.
    pub fn into_source(self) -> S {
        self.src
    }

    /// A non-negative 63-bit integer.
    pub fn int64(&mut self) -> i64 {
        (self.src.uint64() & !(1 << 63)) as i64
    }

    /// A 32-bit value (the high half of one source value).
    pub fn uint32(&mut self) -> u32 {
        (self.src.uint64() >> 32) as u32
    }

    /// A 64-bit value.
    pub fn uint64(&mut self) -> u64 {
        self.src.uint64()
    }

    /// A non-negative 31-bit integer.
    pub fn int32(&mut self) -> i32 {
        (self.src.uint64() >> 33) as i32
    }

    /// Go's `Int`: a non-negative integer (63 bits; Go's 64-bit `int`).
    pub fn int(&mut self) -> i64 {
        (self.src.uint64() << 1 >> 1) as i64
    }

    /// Go's `Uint`: a 64-bit value (Go's 64-bit `uint`).
    pub fn uint(&mut self) -> u64 {
        self.src.uint64()
    }

    /// A value in `[0, n)`.
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn int64_n(&mut self, n: i64) -> i64 {
        if n <= 0 {
            panic!("invalid argument to Int64N");
        }
        self.uint64n(n as u64) as i64
    }

    /// A value in `[0, n)`.
    ///
    /// # Panics
    /// If `n == 0`.
    pub fn uint64_n(&mut self, n: u64) -> u64 {
        if n == 0 {
            panic!("invalid argument to Uint64N");
        }
        self.uint64n(n)
    }

    /// Go's `uint64n` on 64-bit platforms: Lemire's multiply-shift method with
    /// a power-of-two mask fast path and the threshold computed only when the
    /// low half falls below `n`.
    fn uint64n(&mut self, n: u64) -> u64 {
        if n & (n - 1) == 0 {
            return self.uint64() & (n - 1);
        }
        let (mut hi, mut lo) = mul64(self.uint64(), n);
        if lo < n {
            let thresh = n.wrapping_neg() % n;
            while lo < thresh {
                (hi, lo) = mul64(self.uint64(), n);
            }
        }
        hi
    }

    /// A value in `[0, n)`.
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn int32_n(&mut self, n: i32) -> i32 {
        if n <= 0 {
            panic!("invalid argument to Int32N");
        }
        self.uint64n(n as u64) as i32
    }

    /// A value in `[0, n)`.
    ///
    /// # Panics
    /// If `n == 0`.
    pub fn uint32_n(&mut self, n: u32) -> u32 {
        if n == 0 {
            panic!("invalid argument to Uint32N");
        }
        self.uint64n(u64::from(n)) as u32
    }

    /// Go's `IntN`: a value in `[0, n)` (Go's 64-bit `int`).
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn int_n(&mut self, n: i64) -> i64 {
        if n <= 0 {
            panic!("invalid argument to IntN");
        }
        self.uint64n(n as u64) as i64
    }

    /// Go's `UintN`: a value in `[0, n)` (Go's 64-bit `uint`).
    ///
    /// # Panics
    /// If `n == 0`.
    pub fn uint_n(&mut self, n: u64) -> u64 {
        if n == 0 {
            panic!("invalid argument to UintN");
        }
        self.uint64n(n)
    }

    /// Go's generic `N`: a value in `[0, n)` for any primitive integer or
    /// signed [`crate::time::Duration`].
    ///
    /// ```
    /// use rust_stdlib::math::rand::{Pcg, Rand};
    /// use rust_stdlib::time::Duration;
    /// let mut r = Rand::new(Pcg::new(1, 2));
    /// let jitter = r.n(Duration::from_nanos(1_000_000));
    /// assert!((0..1_000_000).contains(&jitter.as_nanos()));
    /// assert!(r.n(10u8) < 10);
    /// ```
    ///
    /// # Panics
    /// If `n <= 0`.
    pub fn n<T: Integer>(&mut self, n: T) -> T {
        match n.positive_u64() {
            Some(bound) => T::from_u64(self.uint64n(bound)),
            None => panic!("invalid argument to N"),
        }
    }

    /// A value in `[0.0, 1.0)` with 53 random bits.
    pub fn float64(&mut self) -> f64 {
        (self.uint64() << 11 >> 11) as f64 / (1u64 << 53) as f64
    }

    /// A value in `[0.0, 1.0)` with 24 random bits.
    pub fn float32(&mut self) -> f32 {
        (self.uint32() << 8 >> 8) as f32 / (1u32 << 24) as f32
    }

    /// A pseudo-random permutation of `0..n`.
    pub fn perm(&mut self, n: usize) -> Vec<usize> {
        let mut p: Vec<usize> = (0..n).collect();
        self.shuffle(n, |i, j| p.swap(i, j));
        p
    }

    /// Fisher-Yates shuffle of `n` elements through `swap(i, j)`.
    pub fn shuffle<F: FnMut(usize, usize)>(&mut self, n: usize, mut swap: F) {
        for i in (1..n).rev() {
            let j = self.uint64n(i as u64 + 1) as usize;
            swap(i, j);
        }
    }

    /// A standard normal value (mean 0, standard deviation 1), using Go's
    /// Marsaglia-Tsang ziggurat over one `uint64` per attempt.
    pub fn norm_float64(&mut self) -> f64 {
        loop {
            let u = self.uint64();
            let j = u as i32; // possibly negative
            let i = ((u >> 32) & 0x7f) as usize;
            if let Some(value) = norm_step(j, i, &mut || self.float64()) {
                return value;
            }
        }
    }

    /// An exponential value with rate 1, using Go's ziggurat over one
    /// `uint64` per attempt.
    pub fn exp_float64(&mut self) -> f64 {
        loop {
            let u = self.uint64();
            let j = u as u32;
            let i = usize::from((u >> 32) as u8);
            if let Some(value) = exp_step(j, i, &mut || self.float64()) {
                return value;
            }
        }
    }
}

/// One attempt of Go's normal ziggurat (shared by v1 and v2, which differ only
/// in how `j` and `i` are drawn and in their `Float64`).
fn norm_step(j: i32, i: usize, float64: &mut dyn FnMut() -> f64) -> Option<f64> {
    let x = f64::from(j) * f64::from(WN[i]);
    if j.unsigned_abs() < KN[i] {
        return Some(x); // 99% of the time this is the result
    }
    if i == 0 {
        // Marsaglia's tail method.
        let (mut x, mut l);
        loop {
            l = log(float64());
            x = -l * RN_INV;
            let y = -log(float64());
            if y + y >= x * x {
                break;
            }
        }
        // Go on arm64 fuses `rn + x` with x's multiplication by 1/rn.
        return Some(match (FUSED_MULTIPLY_ADD, j > 0) {
            (true, true) => (-l).mul_add(RN_INV, RN),
            (true, false) => l.mul_add(RN_INV, -RN),
            (false, true) => RN + x,
            (false, false) => -RN - x,
        });
    }
    let wedge = wedge(FN[i], FN[i - 1], float64() as f32);
    (wedge < exp(-0.5 * x * x) as f32).then_some(x)
}

/// One attempt of Go's exponential ziggurat.
fn exp_step(j: u32, i: usize, float64: &mut dyn FnMut() -> f64) -> Option<f64> {
    let x = f64::from(j) * f64::from(WE[i]);
    if j < KE[i] {
        return Some(x);
    }
    if i == 0 {
        return Some(RE - log(float64()));
    }
    let wedge = wedge(FE[i], FE[i - 1], float64() as f32);
    (wedge < exp(-x) as f32).then_some(x)
}

/// Go's `f[i] + float32(u)*(f[i-1]-f[i])`, fused into FMADDS on arm64.
fn wedge(fi: f32, prev: f32, u: f32) -> f32 {
    if FUSED_MULTIPLY_ADD {
        u.mul_add(prev - fi, fi)
    } else {
        fi + u * (prev - fi)
    }
}

/// Go's `bits.Mul64`: the 128-bit product as (high, low).
fn mul64(x: u64, y: u64) -> (u64, u64) {
    let product = u128::from(x) * u128::from(y);
    ((product >> 64) as u64, product as u64)
}

/// Go's `rand.Zipf`: Zipf-distributed values drawn from a [`Rand`].
#[derive(Debug)]
pub struct Zipf<'a, S> {
    r: &'a mut Rand<S>,
    core: zipf::Core,
}

impl<'a, S: Source> Zipf<'a, S> {
    /// Go's `rand.NewZipf`: values `k` in `[0, imax]` with P(k) proportional
    /// to `(v + k) ** (-s)`. Requires `s > 1` and `v >= 1`; `None` otherwise.
    pub fn new(r: &'a mut Rand<S>, s: f64, v: f64, imax: u64) -> Option<Self> {
        Some(Self {
            r,
            core: zipf::Core::new(s, v, imax)?,
        })
    }

    /// Go's `Zipf.Uint64`: the next value of the distribution.
    pub fn uint64(&mut self) -> u64 {
        let r = &mut *self.r;
        self.core.sample(|| r.float64())
    }
}

mod sealed {
    pub trait Sealed {}
}

/// Integer types accepted by [`Rand::n`] and [`n`], mirroring Go's `intType`.
pub trait Integer: Copy + sealed::Sealed {
    /// `Some(n as u64)` when `n > 0`.
    #[doc(hidden)]
    fn positive_u64(self) -> Option<u64>;
    /// Convert a value known to lie in `[0, n)` back to the type.
    #[doc(hidden)]
    fn from_u64(value: u64) -> Self;
}

macro_rules! integer {
    ($($t:ty),*) => {$(
        impl sealed::Sealed for $t {}
        impl Integer for $t {
            #[allow(unused_comparisons)]
            fn positive_u64(self) -> Option<u64> {
                (self > 0).then_some(self as u64)
            }
            fn from_u64(value: u64) -> Self {
                value as $t
            }
        }
    )*};
}

integer!(i8, i16, i32, i64, isize, u8, u16, u32, u64, usize);

impl sealed::Sealed for crate::time::Duration {}

impl Integer for crate::time::Duration {
    fn positive_u64(self) -> Option<u64> {
        self.as_nanos().positive_u64()
    }
    fn from_u64(value: u64) -> Self {
        crate::time::Duration::from_nanos(value as i64)
    }
}

/// The OS-seeded per-thread [`ChaCha8`] behind the top-level functions.
///
/// Each thread seeds its own generator on first use (see the module
/// documentation for the entropy sources). This is not a CSPRNG and the
/// stream is not reproducible; use [`Pcg`] or [`ChaCha8`] with an explicit
/// seed for reproducible sequences.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct GlobalSource;

thread_local! {
    static GLOBAL: RefCell<ChaCha8> = RefCell::new(ChaCha8::new(os_seed()));
}

impl Source for GlobalSource {
    fn uint64(&mut self) -> u64 {
        GLOBAL
            .try_with(|state| state.borrow_mut().uint64())
            // During thread-local destruction fall back to a fresh generator.
            .unwrap_or_else(|_| ChaCha8::new(os_seed()).uint64())
    }
}

/// Gather a 32-byte seed from std-only entropy sources.
fn os_seed() -> [u8; 32] {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let keys = RandomState::new();
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_nanos())
        .unwrap_or(0);
    let local = 0u8;
    let mut seed = [0u8; 32];
    for (i, chunk) in seed.chunks_mut(8).enumerate() {
        let mut hasher = keys.build_hasher();
        hasher.write_usize(i);
        hasher.write_u128(nanos);
        hasher.write_u32(std::process::id());
        std::hash::Hash::hash(&std::thread::current().id(), &mut hasher);
        hasher.write_u64(COUNTER.fetch_add(1, Ordering::Relaxed));
        hasher.write_usize(std::ptr::addr_of!(local) as usize);
        chunk.copy_from_slice(&hasher.finish().to_le_bytes());
    }
    #[cfg(unix)]
    {
        use std::io::Read;
        let mut device = [0u8; 32];
        let read =
            std::fs::File::open("/dev/urandom").and_then(|mut file| file.read_exact(&mut device));
        if read.is_ok() {
            for (byte, extra) in seed.iter_mut().zip(device) {
                *byte ^= extra;
            }
        }
    }
    seed
}

fn global() -> Rand<GlobalSource> {
    Rand::new(GlobalSource)
}

/// Go's top-level `Int64` from the OS-seeded [`GlobalSource`].
pub fn int64() -> i64 {
    global().int64()
}

/// Go's top-level `Uint32`.
pub fn uint32() -> u32 {
    global().uint32()
}

/// Go's top-level `Uint64`.
pub fn uint64() -> u64 {
    global().uint64()
}

/// Go's top-level `Int32`.
pub fn int32() -> i32 {
    global().int32()
}

/// Go's top-level `Int` (63 bits).
pub fn int() -> i64 {
    global().int()
}

/// Go's top-level `Uint` (64 bits).
pub fn uint() -> u64 {
    global().uint()
}

/// Go's top-level `Int64N`. Panics if `n <= 0`.
pub fn int64_n(n: i64) -> i64 {
    global().int64_n(n)
}

/// Go's top-level `Uint64N`. Panics if `n == 0`.
pub fn uint64_n(n: u64) -> u64 {
    global().uint64_n(n)
}

/// Go's top-level `Int32N`. Panics if `n <= 0`.
pub fn int32_n(n: i32) -> i32 {
    global().int32_n(n)
}

/// Go's top-level `Uint32N`. Panics if `n == 0`.
pub fn uint32_n(n: u32) -> u32 {
    global().uint32_n(n)
}

/// Go's top-level `IntN`. Panics if `n <= 0`.
pub fn int_n(n: i64) -> i64 {
    global().int_n(n)
}

/// Go's top-level `UintN`. Panics if `n == 0`.
pub fn uint_n(n: u64) -> u64 {
    global().uint_n(n)
}

/// Go's top-level generic `N`. Panics if `n <= 0`.
pub fn n<T: Integer>(n: T) -> T {
    global().n(n)
}

/// Go's top-level `Float64`.
pub fn float64() -> f64 {
    global().float64()
}

/// Go's top-level `Float32`.
pub fn float32() -> f32 {
    global().float32()
}

/// Go's top-level `Perm`.
pub fn perm(n: usize) -> Vec<usize> {
    global().perm(n)
}

/// Go's top-level `Shuffle`. `swap` may itself call these functions.
pub fn shuffle<F: FnMut(usize, usize)>(n: usize, swap: F) {
    global().shuffle(n, swap)
}

/// Go's top-level `NormFloat64`.
pub fn norm_float64() -> f64 {
    global().norm_float64()
}

/// Go's top-level `ExpFloat64`.
pub fn exp_float64() -> f64 {
    global().exp_float64()
}
